from pathlib import Path
import re,json,html
from PIL import Image
R=Path(__file__).resolve().parents[3]; D=R/'docs/editorial/oct20-new-blogs'
base=(R/'journal/equipment-calibration-log/index.html').read_text()
style=re.search(r'<style>.*?</style>',base,re.S)[0]
nav=re.search(r'<header class="nav">.*?</header>',base,re.S)[0]
footer=base[base.index('<footer class="site">'):]
items=[('inventory-count-sheet','Inventory Count Sheet: Free Template and Filled Example','Download a printable inventory count sheet and follow a worked stocktake example covering blind counts, recounts, movement cutoffs and reviewed adjustments.','inventory-body.html','exec-4aafc90c-75f4-430c-9085-e54936186a7d.png','Hands counting textile stock beside a clipboard and labeled storage bins in a small stockroom.'),('production-schedule-template','Production Schedule Template for a Small Workshop','Use a free printable production schedule template with a filled weekly example, setup and run-time calculations, material checks and a rush-order capacity test.','production-body.html','exec-4f79ee00-11aa-4b02-bb96-c4d930c7dcfa.png','Canvas pouch materials, sewing equipment and a weekly planning sheet arranged on a workshop bench.')]
for slug,title,desc,bodyfile,img,alt in items:
 image='/images/journal/'+slug+'-20261020.webp';im=Image.open(R.parent/'generated_images'/img);im.resize((1200,800)).save(R/image.lstrip('/'),'WEBP',quality=84)
 body=(D/bodyfile).read_text();heads=re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',body)
 toc='<nav class="toc" aria-label="In this guide"><strong>In this guide</strong><ul>'+''.join(f'<li><a href="#{a}">{b}</a></li>' for a,b in heads)+'</ul></nav>'
 body=body.replace('</div>','</div>'+toc,1)
 url='https://nexalyplanner.com/journal/'+slug+'/'
 schema={'@context':'https://schema.org','@type':'BlogPosting','@id':url+'#article','headline':title,'description':desc,'image':'https://nexalyplanner.com'+image,'mainEntityOfPage':url,'author':{'@type':'Organization','name':'NexalyPlanner','url':'https://nexalyplanner.com/about/'},'publisher':{'@type':'Organization','name':'NexalyPlanner','url':'https://nexalyplanner.com/'},'datePublished':'2026-10-20','dateModified':'2026-10-20','inLanguage':'en-US'}
 source=f'<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><link rel="canonical" href="{url}"><meta property="og:image" content="https://nexalyplanner.com{image}"><meta name="twitter:image" content="https://nexalyplanner.com{image}"><meta property="og:image:alt" content="{alt}"><meta property="article:published_time" content="2026-10-20"><meta property="article:modified_time" content="2026-10-20"><meta property="og:type" content="article">'+style+'<link rel="stylesheet" href="/assets/css/style.css"><script type="application/ld+json">'+json.dumps(schema)+'</script></head><body>'+nav+f'<header class="article-hero"><div class="brand">NEXALYPLANNER JOURNAL</div><h1>{title}</h1><p class="metadata">By NexalyPlanner · Published October 20, 2026</p></header><main><p class="toplink"><a href="/journal/">Back to the NexalyPlanner Journal</a></p><article class="reading"><figure class="article-feature"><img src="{image}" width="1200" height="800" alt="{alt}" fetchpriority="high" decoding="async"><figcaption>AI-generated editorial illustration. The worked examples below are fictional.</figcaption></figure>'+body+'</article></main>'+footer
 p=R/'journal'/slug/'index.html';p.parent.mkdir(exist_ok=True);p.write_text(source)
# Original paper forms, no data entry or implied storage.
css='body{font:15px/1.5 system-ui;color:#163044;margin:28px}h1{font-size:26px}h2{font-size:20px}p{max-width:950px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #78909a;padding:8px;text-align:left;overflow-wrap:anywhere}td{height:42px}th{background:#e7f2ef;font-size:12px}.scroll{overflow:auto}table{min-width:850px}.fields{line-height:2.6}.page{max-width:1100px;margin:auto auto 50px}@media print{@page{size:landscape;margin:12mm}.page{break-after:page;margin:0}.page:last-child{break-after:auto}.screen{display:none}.scroll{overflow:visible}table{min-width:0}body{font-size:10pt;margin:0}td{height:28px;padding:5px}th{font-size:8pt;padding:5px}.fields{line-height:1.7}h1{font-size:18pt;margin:0 0 6px}h2{font-size:13pt;margin:4px 0}p{margin:8px 0}}'
def table(headers,n=7):return '<div class="scroll" tabindex="0" role="region" aria-label="Blank worksheet; scroll horizontally"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td></td>' for _ in headers)+'</tr>' for i in range(n))+'</tbody></table></div>'
forms={
'inventory-count-sheet': [('Blind count page','Count ID: __________ Date: __________ Cutoff time: __________ Location / zone: __________<br>Counter: __________ Page: ____ of ____ Unit / pack definitions: ____________________',['SKU / description','Bin / status / lot if used','Unit','First count','Recount','Counter / time','Movement reference'],'Blank means uncounted. Zero means checked and none found. Keep expected quantities on the review page. Record receipts, dispatches and transfers during counting.'),('Reconciliation page','Count ID: __________ Snapshot time: __________ Reviewer: __________ Review date: __________',['SKU / bin / status','Comparable expected qty','Final counted qty','Difference: counted − expected','Cause / evidence','Approved correction / posting ref','Reviewer'],'Reconcile movement timing first. Keep original counts. Correct missing transactions once; do not also post a duplicate adjustment. A zero net total can hide row-level errors.')],
'production-schedule-template': [('Weekly resource plan','Week starting: __________ Resource: __________ Owner: __________ Plan version: __________',['Day / date','Available hours after deductions','Jobs / sequence','Booked hours','Unallocated hours','Start conditions / blockers','Owner / revision'], 'Use one resource per page. Check operator time separately when one person serves multiple machines. Unallocated time later in the week does not resolve an earlier due-date conflict.'),('Job detail page','Week starting: __________ Prepared by: __________ Version / review time: __________',['Job / SKU / quantity','Resource / owner','Materials ready / predecessor','Setup hours','Run minutes per unit','Check / pack hours','Planned start / finish / due'], 'Planned hours = setup + quantity × run minutes per unit ÷ 60 + check/pack hours. Record actual hours, accepted quantity and unresolved work separately below. This paper form does not calculate or reserve capacity.')]
}
for slug,pages in forms.items():
 t='Inventory count sheet' if slug.startswith('inventory') else 'Production schedule template'
 out=f'<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>{t} | NexalyPlanner</title><style>{css}</style></head><body><p class="screen">Free printable worksheet. Use your browser Print menu (Ctrl/Cmd+P) and select landscape or Save as PDF. Write on paper or annotate the saved PDF. This file does not save entries or calculate.</p>'
 for heading,fields,headers,note in pages:out+=f'<section class="page"><h1>{t}</h1><h2>{heading}</h2><p class="fields">{fields}</p>'+table(headers)+f'<p>{note}</p><p class="fields">Actuals / unresolved work / follow-up: __________________________________________________________<br>________________________________________________________________________________________</p><p>NexalyPlanner · Free original template · Guide: https://nexalyplanner.com/journal/{slug}/</p></section>'
 (R/'downloads/templates'/f'{slug}.html').write_text(out+'</body></html>')
# Contextual inbound links from relevant nonpaid pages.
p=R/'tools/physical-count-adjustment-worksheet/index.html';s=p.read_text();s=s.replace('</main>','<section class="tool-panel no-print"><h2>Prepare your physical count</h2><p>Use the <a href="/journal/inventory-count-sheet/">inventory count sheet and filled stocktake example</a> to record observations, reconcile movement timing and review differences before entering comparable quantities here.</p></section></main>',1);p.write_text(s)
p=R/'journal/batch-lot-traceability-log/index.html';s=p.read_text();s=s.replace('<h2 id="setup">','<p>Before starting a batch, use the <a href="/journal/production-schedule-template/">production schedule template for a small workshop</a> to check material readiness and available workstation hours. Keep planned dates separate from the actual lot history.</p><h2 id="setup">',1);p.write_text(s)
print('Authored two articles, two printable downloads and contextual inbound links')
